const args = $input.first().json;
if (!args.descripcion || String(args.descripcion).trim() === '') {
  return [{ json: { status: 'ERROR', _skip: true, message_to_agent: 'Faltó descripcion del uso.' } }];
}
return [{ json: args }];

// v2 — Fix F1: filtra records vacíos.
// Mejora: cuando Tecnologías recomendadas viene vacío (datos no cargados en Airtable),
// el message_to_agent sugiere al agente derivar al comercial.

const apps = $input.all()
  .map(i => i.json)
  .filter(a => a && a.id && a['Aplicación']);
const args = $('Execute Workflow Trigger').first().json;
const query = String(args.descripcion).toLowerCase();

function score(app) {
  const keywords = String(app['Keywords cliente'] || '').toLowerCase().split(/[,;]+/).map(k => k.trim()).filter(Boolean);
  const nombreApp = String(app['Aplicación'] || '').toLowerCase();
  let s = 0;
  for (const kw of keywords) {
    if (kw && query.includes(kw)) s += 2;
  }
  const palabrasNombre = nombreApp.split(/\s+/);
  for (const p of palabrasNombre) {
    if (p.length > 3 && query.includes(p)) s += 1;
  }
  return s;
}

const scored = apps.map(a => ({ app: a, s: score(a) })).filter(x => x.s >= 1).sort((a, b) => b.s - a.s);

if (scored.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré aplicación que matchee "${args.descripcion}". Sugerí al cliente más detalle (sobre qué material, qué producto final) o derivá al comercial.`,
    trace_id: $execution.id
  } }];
}

const best = scored[0].app;
const tecnologiasNombres = best['Nombre (from Tecnologías recomendadas)'] || [];
const tecnologiasIds = best['Tecnologías recomendadas'] || [];

return [{ json: {
  status: 'RESOLVED',
  data: {
    aplicacion_match: best['Aplicación'] || '',
    categoria: best['Categoría'] || '',
    tecnologias_recomendadas: tecnologiasNombres,
    sustratos_tipicos: best['Sustratos típicos'] || [],
    notas_para_agente: best['Notas para asesoramiento'] || ''
  },
  message_to_agent: tecnologiasNombres.length > 0
    ? `Aplicación detectada: ${best['Aplicación']}. Tecnologías recomendadas: ${tecnologiasNombres.join(', ')}. Sustratos típicos: ${(best['Sustratos típicos'] || []).join(', ')}.`
    : `Aplicación detectada: ${best['Aplicación']} (categoría ${best['Categoría']}). El catálogo todavía no tiene tecnologías recomendadas cargadas para esta aplicación — derivá al comercial para asesoramiento técnico específico, o sugerí al cliente describir el tipo de material y volumen.`,
  trace_id: $execution.id
} }];
